      chromium: browser.version(),
    },
    runs,
    iterations,
    contracts,
    builds,
    summary,
    raw,
  };
  await writeFile(
    join(output, 'results.json'),
    JSON.stringify(result, null, 2) + '\n',
  );
  console.table(
    summary.map((r) => ({
      case: r.case,
      count: r.count,
      variant: r.label,
      mount: r.mount.median,
      ready: r.ready.median,
      heap: r.heapMiB.median,
    })),
