      const comments = await page.evaluate(() => {
        const walker=document.createTreeWalker(document.getElementById('mount'),NodeFilter.SHOW_COMMENT);
        let all=0,forComments=0;while(walker.nextNode()){all++;if(walker.currentNode.nodeValue.startsWith('craft-for:'))forComments++;}
        return {all,forComments};
      });
      await page.evaluate(() => window.__compilerBench.run('destroy'));
      assert.equal(await page.locator('#mount').textContent(), '');
      assert.deepEqual(errors, []);
      traces.push({ label, trace, comments });
      await context.close();
    }
    for (const trace of traces.slice(1))
      assert.deepEqual(
        traces[0].trace,
        trace.trace,
        `${kind}/${trace.label}: DOM equivalence`,
      );
    contracts.push({ case: kind, passed: true, steps: traces[0].trace.length, variants: traces.map(({label,comments})=>({label,comments})) });
  }
  const jobs = [];
  for (let run = 0; run < runs; run++)
    for (const kind of selected)
      for (const count of kind === 'fields' ? [128] : counts)
        for (const label of servers.keys())
          jobs.push({ run, kind, count, label });
  // Seeded shuffle: fresh contexts, interleaved variants and reproducible order.
  let seed = 16112026;
  const random = () => {
    seed = (1664525 * seed + 1013904223) >>> 0;
    return seed / 2 ** 32;
  };
  // Randomized blocks keep both variants of a case adjacent; their order
  // alternates by run to balance order effects during this confirmation.
  const blocks=[];
  for(const job of jobs){
    const previous=blocks.at(-1);
    if(previous&&previous[0].run===job.run&&previous[0].kind===job.kind&&previous[0].count===job.count)previous.push(job);
    else blocks.push([job]);
  }
  for(const block of blocks)if(block[0].run%2)block.reverse();
  for(let i=blocks.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[blocks[i],blocks[j]]=[blocks[j],blocks[i]];}
  jobs.splice(0,jobs.length,...blocks.flat());
  const raw = [];
  for (const job of jobs) {
    const { page, context, errors } = await open(
      servers.get(job.label).url,
      job.kind,
      job.count,
    );
    const data = await page.evaluate(() => ({
      mount: window.__compilerBench.mountMs,
      ready: window.__compilerBench.navigationToReadyMs,
      twoFrames: window.__compilerBench.twoFramesMs,
      nodes: document.getElementById('mount').querySelectorAll('*').length,
    }));
    const samples = {};
    for (let loop = 0; loop < iterations + 2; loop++)
      for (const action of actions(job.kind)) {
        let ms;
        try {
          ms = await page.evaluate(
            (a) => window.__compilerBench.run(a),
            action,
          );
        } catch (error) {
          await writeFile(
            join(output, 'failed-case.json'),
            JSON.stringify({ job, loop, action, errors }, null, 2),
          );
          throw error;
        }
        if (loop >= 2) (samples[action] ??= []).push(ms);
      }
    const cdp = await context.newCDPSession(page);
    await cdp.send('HeapProfiler.collectGarbage');
    data.heapMiB =
      (await cdp.send('Runtime.getHeapUsage')).usedSize / 1024 / 1024;
    data.actions = Object.fromEntries(
      Object.entries(samples).map(([name, values]) => [name, median(values)]),
    );
    assert.deepEqual(errors, []);
    raw.push({ ...job, ...data });
    await context.close();
    if (raw.length % 10 === 0)
      console.log(`${raw.length}/${jobs.length} navigations`);
  }
  const summary = [];
  for (const kind of selected)
    for (const count of kind === 'fields' ? [128] : counts)
      for (const label of servers.keys()) {
        const rows = raw.filter(
          (r) => r.kind === kind && r.count === count && r.label === label,
        );
        summary.push({
          case: kind,
          count,
          label,
          ...Object.fromEntries(
            ['mount', 'ready', 'twoFrames', 'heapMiB'].map((key) => [
              key,
              distribution(rows.map((r) => r[key])),
            ]),
          ),
          actions: Object.fromEntries(
            [...new Set(actions(kind))].map((key) => [
              key,
              distribution(rows.map((r) => r.actions[key])),
            ]),
          ),
        });
      }
  const result = {
    timestamp: new Date().toISOString(),
    base: execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: root,
      encoding: 'utf8',
    }).trim(),
    sourceSha256,
    environment: {
      cpu: cpus()[0].model,
      platform: platform(),
      release: release(),
      node: process.version,
      chromium: browser.version(),
    },
    runs,
    iterations,
    contracts,
    builds,
    summary,
    raw,
  };
  await writeFile(
    join(output, 'results.json'),
    JSON.stringify(result, null, 2) + '\n',
  );
  console.table(
    summary.map((r) => ({
      case: r.case,
      count: r.count,
      variant: r.label,
      mount: r.mount.median,
      ready: r.ready.median,
      heap: r.heapMiB.median,
    })),
  );
  console.log(join(output, 'results.json'));
} finally {
  await browser?.close();
  for (const { server } of servers.values())
    await new Promise((done) => server.httpServer.close(done));
}

