    summary.map((r) => ({
      case: r.case,
      count: r.count,
      variant: r.label,
      mount: r.mount.median,
      ready: r.ready.median,
      heap: r.heapMiB.median,
    })),
  );
  console.log(join(output, 'results.json'));
} finally {
  await browser?.close();
  for (const { server } of servers.values())
    await new Promise((done) => server.httpServer.close(done));
}

