  let plain = 0,
    gzip = 0;
  for (const item of await readdir(path, { withFileTypes: true })) {
    const file = join(path, item.name);
    if (item.isDirectory()) {
      const child = await bytes(file);
      plain += child.plain;
      gzip += child.gzip;
