        ts.isCallExpression(n) &&
        ts.isIdentifier(n.expression) &&
        helpers.has(n.expression.text) &&
        sameBinding(n.expression, helperDeclarations.get(n.expression.text));
      const isText =
        literal(n) !== undefined ||
