    `export const Row=craftComponent('StyleIslandSUFFIX',{},()=>div({attrs:{role:'row'}},[span({style:styleRecord},'styled'),span('plain')]));export const App=craftComponent('StyleIslandOwnerSUFFIX',{},()=>Row({}));`,
    { styleRecord },
