    JSON.stringify(workspace) +
    ';',
);
runner = replaceOnce(
  runner,
  "    const enabled = mode !== 'runtime';",
  `    const {craftCompiler} = await import(pathToFileURL(join(libraryRoot,'dist/libs/compiler/src/vite.js')));
    const enabled = mode !== 'runtime';`,
);
runner = replaceOnce(
